import pytest

def diskon(harga, persen):
    if not 0 <= persen <= 100:
        raise ValueError("persen tidak valid")
    return harga - harga * persen // 100

def test_diskon_normal():
    assert diskon(100_000, 10) == 90_000

def test_persen_tidak_valid():
    with pytest.raises(ValueError):
        diskon(10_000, 120)

